import{z as B,x as n,o as e,c as o,q as A,j as l,D as a,d as r,s,S as i}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"KV 测量的坑","description":"","frontmatter":{"title":"KV 测量的坑","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/kv-measurement-pitfalls.md","filePath":"llm/kv-measurement-pitfalls.md","lastUpdated":1791413859000}'),d={name:"llm/kv-measurement-pitfalls.md"};function m(p,E,T,c,D,u){const t=n("Mermaid");return e(),o("div",null,[E[2]||(E[2]=A('<h1 id="kv-测量的坑" tabindex="-1">KV 测量的坑 <a class="header-anchor" href="#kv-测量的坑" aria-label="Permalink to &quot;KV 测量的坑&quot;">​</a></h1><div class="epigraph"><p>利用率、命中率、压缩率，每一个数字都对——只要你不问分母是谁；KV 报表的第一义务是写清口径。</p><footer>—— 据 Kwon et al., SOSP 2023 的测量口径与各推理引擎的指标实践整理</footer></div><p>前九课定义了一堆量：三种利用率口径、前缀命中率、碎片率、接受长度分布、压缩率、每 token 有效字节。本课写它们怎么在报表里被算错。坑的共同结构只有一个：<strong>用外部代理反推内部状态</strong>。显存占用、请求计数、理论压缩率都是代理；唯一可信的源头是第一课那台状态机——块表与页池的内部账。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>四类高频错报。<strong>利用率</strong>：reserved、allocated、in-use 三口径混用，「利用率 95%」可以指页都发出去了（allocated/reserved），也可以指页内几乎无空槽（in-use/allocated），两者之间可以差一整个内部碎片。显存占用更糟：nvidia-smi 的数字里混着权重、激活、CUDA 上下文与分配器预留，从中「反推」KV 用量等于把四个变量当一个读。<strong>命中率</strong>：一份共享页被 \\(N\\) 条请求引用，按请求计数分子就是 \\(N\\)，物理省的是 1——分母选错，命中率高估 \\(N\\) 倍；分母还必须是「可命中请求」，随机对话站点天生低命中，不代表实现坏。<strong>压缩收益</strong>：「存 8-bit」不等于「带宽减半」，若核读出后先解回 FP16，容量降了而每步时间几乎不动——<a href="/llm/kv-int8-fp8">profiler 里的实际事务宽度</a>才是证据。<strong>归因</strong>：TTFT 降了，是前缀命中、分块预填还是新驱动？没有对照开关的归因都是编故事。</p><p><span class="marginnote">术语翻译：内部碎片就是「分给你的房间没用满」——页按固定大小发出去了，请求只住了一半格子，空着的部分谁也不能再租。与之相对，外部碎片是「房间还有，但都不连片」。碎片率高时，利用率再好看也接不下新请求。</span></p>',6)),(e(),l(i,null,{default:a(()=>[s(t,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%8A%A5%E8%A1%A8%E5%86%99%3A%20%E5%88%A9%E7%94%A8%E7%8E%87%2095%25%22%5D%20--%3E%20A%7B%22%E5%88%86%E6%AF%8D%E5%88%86%E5%AD%90%E6%98%AF%E8%B0%81%3F%22%7D%0A%20%20A%20--%3E%7C%22allocated%20%E9%99%A4%E4%BB%A5%20reserved%22%7C%20A1%5B%22%E9%A1%B5%E9%83%BD%E5%8F%91%E5%87%BA%E5%8E%BB%E4%BA%86%2C%20%E4%BD%86%E9%A1%B5%E5%86%85%E5%8F%AF%E8%83%BD%E5%85%A8%E6%98%AF%E7%A9%BA%E6%A7%BD%22%5D%0A%20%20A%20--%3E%7C%22in-use%20%E9%99%A4%E4%BB%A5%20allocated%22%7C%20A2%5B%22%E9%A1%B5%E5%86%85%E5%87%A0%E4%B9%8E%E6%97%A0%E7%A9%BA%E6%A7%BD%2C%20%E7%9C%9F%E7%9A%84%E8%A3%85%E6%BB%A1%22%5D%0A%20%20A1%20--%3E%20G%5B%22%E4%B8%A4%E4%B8%AA%2095%25%20%E4%B9%8B%E9%97%B4%E9%9A%94%E7%9D%80%E4%B8%80%E6%95%B4%E4%B8%AA%E5%86%85%E9%83%A8%E7%A2%8E%E7%89%87%22%5D%0A%20%20A2%20--%3E%20G%0A%20%20G%20--%3E%20L%5B%22%E8%A7%A3%E6%B3%95%3A%20%E4%B8%89%E5%8F%A3%E5%BE%84%E5%B9%B6%E5%88%97%E7%94%BB%2C%20%E5%8F%A3%E5%BE%84%E5%86%99%E8%BF%9B%E8%84%9A%E6%B3%A8%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>仪表从状态机导出，不从代理反推。</p><ul><li><strong>容量页</strong>：in-use、allocated、reserved 三条曲线并列画，碎片率 \\(1-{\\rm in\\text{-}use}/{\\rm allocated}\\) 单独一条；峰值按分位记，不按均值。</li><li><strong>共享页</strong>：两个口径并行——请求级「token 节省」（分子按引用次数）与页级「物理节省」（分子按物理页数），中间的差就是共享倍数本身。</li><li><strong>时间页</strong>：TTFT/TPOT 用<a href="/llm/ttft-percentiles">分位数口径</a>，TPOT 长尾单独归因：投机解码的接受长度方差（上一课的监控项）是头号嫌疑人。</li><li><strong>对照纪律</strong>：每个收益数字必须配一个「关掉该开关」的同负载对照；<a href="/llm/serving-metrics">基准条件</a>——并发、长度分布、是否共享系统提示、页大小、精度——写不进图就要写进脚注，否则数字不可复现。</li></ul><p><span class="marginnote">数字实例：allocated 是 10 GiB、in-use 只有 7 GiB 时，碎片率 \\(1 - 7/10 = 30\\%\\)——已分配的内存里三成是空槽。注意它不等于「还有 3 GiB 可用」：那些格子已被某个页占着号，只是没住满。</span></p>',4)),(e(),l(i,null,{default:a(()=>[s(t,{id:"mermaid-48",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E5%9D%97%E8%A1%A8%E4%B8%8E%E9%A1%B5%E6%B1%A0%EF%BC%9A%E5%86%85%E9%83%A8%E8%B4%A6%22%5D%20--%3E%20UTIL%5B%22%E5%88%A9%E7%94%A8%E7%8E%87%EF%BC%9Ain-use%20%2F%20allocated%20%2F%20reserved%22%5D%0A%20%20SRC%20--%3E%20HIT%5B%22%E5%91%BD%E4%B8%AD%E7%8E%87%EF%BC%9A%E8%AF%B7%E6%B1%82%E7%BA%A7%E4%B8%8E%E9%A1%B5%E7%BA%A7%E5%8F%8C%E5%8F%A3%E5%BE%84%22%5D%0A%20%20SRC%20--%3E%20COMP%5B%22%E5%8E%8B%E7%BC%A9%EF%BC%9A%E6%9C%89%E6%95%88%E5%AD%97%E8%8A%82%E8%A1%A8%20%C3%97%20%E4%BA%8B%E5%8A%A1%E5%AE%BD%E5%BA%A6%22%5D%0A%20%20AGENT%5B%22%E5%A4%96%E9%83%A8%E4%BB%A3%E7%90%86%EF%BC%9A%E6%98%BE%E5%AD%98%E5%8D%A0%E7%94%A8%20%2F%20%E8%AF%B7%E6%B1%82%E6%95%B0%22%5D%20--%3E%20X%5B%22%E5%8F%AA%E5%81%9A%E6%97%81%E8%AF%81%EF%BC%8C%E4%B8%8D%E5%81%9A%E5%88%86%E6%AF%8D%22%5D%0A%20%20UTIL%20--%3E%20REP%5B%22%E6%8A%A5%E8%A1%A8%EF%BC%9A%E5%8F%A3%E5%BE%84%E5%86%99%E5%85%A5%E8%84%9A%E6%B3%A8%22%5D%0A%20%20HIT%20--%3E%20REP%0A%20%20COMP%20--%3E%20REP%0A%20%20REP%20--%3E%20AB%5B%22A%2FB%20%E5%AF%B9%E7%85%A7%EF%BC%9A%E5%BC%80%E5%85%B3%E5%90%8C%E8%B4%9F%E8%BD%BD%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么内部账是唯一源：利用率的三个口径、命中的两个口径，每一个都是状态机的一个合法投影——三口径在课二的定义里就同时成立，坑不在数字错，在投影被当成了全貌。投影必须成对出现：报 in-use 就要带 allocated，报请求级命中就要带页级命中，单独发布任何一个投影都是在替读者选择结论。压缩收益的机制同理：字节表是静态账，<a href="/llm/arithmetic-intensity-decode">事务宽度</a>是动态账，收益取两者交集，只报静态表的「4 倍压缩」在核不支持时就是虚数。</p><p><span class="marginnote">命中率 90% 而 TTFT 只降 10% 是常见的「假警报」：命中的多是短系统提示，TTFT 的大头在长文档前缀。收益要按 token 加权再按长度分桶看，按请求计数的命中率解释不了延迟变化。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>有些量本质上测不准：碎片率在动态负载下是瞬时值，采样间隔决定了你看见的是峰还是谷；跨实例聚合的命中率会被<a href="/llm/kv-aware-routing">路由</a>的放置策略塑造，改路由等于改分子。驱逐与合并的评测有自己的坑：短补全的困惑度对误杀几乎无感（<a href="/llm/kv-eviction-heuristics">驱逐课</a>已立规），长上下文任务的掉点要单独预算，吞吐提升可能只是把损失搬到了没人测的任务上。最后，报表的读者是容量规划与排障两个角色，前者要分位数与口径，后者要时间线与归因——一张不分读者的总表，通常两个角色都用不上。</p><p><span class="marginnote">常见误区：把瞬时碎片率当成常量去调容量。它随负载起伏，1 秒采样和 1 分钟采样看到的可能是峰、谷两幅图；容量决策要用分位峰值，排障才看逐条时间线。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一切口径错报的共同结构：用外部代理反推内部状态；唯一源是块表与页池的账。</li><li>利用率三口径并列画；碎片率的分母是 allocated，不是 reserved。</li><li>命中率分请求级与页级双口径，分母是可命中请求；共享倍数就是两口径之差。</li><li>压缩收益 = 静态字节表 × 动态事务宽度；「存了低精度」不是「省了带宽」。</li><li>每个收益配对照开关，基准条件进脚注；TPOT 长尾先查接受长度方差。</li><li>出处：Kwon et al., SOSP 2023（测量与碎片口径）；指标定义据本仓库服务指标、TTFT 分位课。</li></ul>',8))])}const h=B(d,[["render",m]]);export{F as __pageData,h as default};
